fast_pseudocode:
# AFTER (regressed): autotune selects XBLOCK=256, regs jump to 32
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 1024}, num_warps=8, num_stages=2),
        triton.Config({'XBLOCK': 512},  num_warps=4, num_stages=2),
        triton.Config({'XBLOCK': 256},  num_warps=4, num_stages=2),
        triton.Config({'XBLOCK': 128},  num_warps=4, num_stages=2),
    ],
    key=['xnumel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    # autotuner picks XBLOCK=256
    # 32 regs/thread, 4.4B instructions total — 6x more work

grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](...)  # no XBLOCK kwarg — autotuner controls it

